sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_GetStores(vExpected)
	{
		function TestCase_GetStores_CheckResult(vInput,vExpected,vResult)
		{
			if (x_snc_devtools.IsArray(vResult) == false)
			{
				return false;
			}
			var aStores = vResult;
			var aExpected = x_snc_devtools.GetArrayValue(vExpected);
			for (var nExpected = 0; nExpected < aExpected.length; nExpected++)
			{
				var strName = aExpected[nExpected];
				var bFound = false;
				for (var nStore = 0; nStore < aStores.length; nStore++)
				{
					var store = aStores[nStore];
					if (strName == x_snc_devtools.GetValue(store,'name'))
					{
						bFound = true;
					}
				}
				if (bFound == false)
				{
					return false;
				}
			}
			return true;
		}
		
		test.TestCase(
			'Function GetStores()',
			GetStores,
			{
			},
			vExpected,
			TestCase_GetStores_CheckResult);
	}
		
	TestCase_GetStores([]);

	var grStore = new GlideRecord('x_snc_stores_store');
	grStore.initialize();
	grStore.name = 'TEST1';
	grStore.insert();

	var grStore = new GlideRecord('x_snc_stores_store');
	grStore.initialize();
	grStore.active = true;
	grStore.name = 'TEST2';
	grStore.insert();

	TestCase_GetStores(['TEST2']);

	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
